<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {Activity,ClipboardCheck,LoaderCircle,RefreshCw,ShieldCheck} from 'lucide-vue-next';
import {post,queryString,request} from '../api';
import {useAppStore} from '../stores/app';
interface Operation{id:string;kind:string;actorName:string;ref?:string;key?:{namespace:string;repo:string};state:string;createdAt:string;updatedAt:string;reasonCode?:string;anchors:Record<string,unknown>}
const app=useAppStore(),route=useRoute(),router=useRouter(),items=ref<Operation[]>([]),selected=ref<Operation>(),page=ref(1),total=ref(0),filter=ref(''),error=ref(''),loading=ref(false),busy=ref(false),health=ref<any>();let generation=0;
const owner=computed(()=>app.status?.identity?.kind==='owner'),labels:Record<string,string>={prepared:'已登记',running:'执行中',succeeded:'已核验完成',failed:'写入前已停止','reconciliation-required':'待核对'};
const timestamp=(value:string)=>new Date(value).toLocaleString('zh-CN',{hour12:false});
async function load(){const current=++generation;loading.value=true;error.value='';try{const result=await request<{items:Operation[];total:number}>('/operations'+queryString({page:page.value,pageSize:30,...(filter.value?{state:filter.value}:{})}));if(current!==generation)return;items.value=result.items;total.value=result.total;if(typeof route.query.operation==='string')selected.value=await request('/operations/'+encodeURIComponent(route.query.operation));if(owner.value)health.value=await request('/operations/health');}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function choose(item:Operation){selected.value=item;await router.replace({query:{operation:item.id}});}
async function reconcile(){if(!selected.value||busy.value)return;if(!await app.confirmAction('将读取固定提交、合并祖先或发布资产，核对已有结果；不会再次提交、合并或发布。',{title:'核对现有操作结果',confirmLabel:'开始核对'}))return;busy.value=true;error.value='';try{selected.value=await post('/operations/'+selected.value.id+'/reconcile');await load();app.notify(selected.value?.state==='succeeded'?'已核验原操作完成。':'仍不能证明操作结果，请保留输入并对照目标版本。');}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function maintenance(){if(!owner.value||busy.value)return;const draining=health.value?.runtime?.mode==='draining';if(!await app.confirmAction(draining?'恢复接受新写入？':'进入维护会停止新保存和提交，等待已接受的操作排空。仍可浏览已保存内容；尚未保存的输入留在当前页面，维护结束后再保存和离开。',{title:draining?'恢复写入':'进入停写维护',confirmLabel:draining?'恢复写入':'停写并排空'}))return;busy.value=true;error.value='';try{await post('/maintenance/'+(draining?'resume':'drain'));await load();}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
watch(()=>route.query.operation,()=>{if(typeof route.query.operation==='string'&&selected.value?.id!==route.query.operation)void load();});watch(filter,()=>{page.value=1;void load();});onMounted(load);onBeforeUnmount(()=>generation++);
</script>
<template><section class="operations-page"><header class="page-title-row"><div><span class="eyebrow">工作状态与故障核对</span><h1><Activity :size="25"/>操作核对</h1><p>结果未知时先读取已有证据，避免重复提交。当前页面不展示样本正文或访问令牌。</p></div><button class="btn" :disabled="loading||busy" @click="load"><RefreshCw :size="15"/>刷新状态</button></header>
<section v-if="owner&&health" class="panel operations-health"><header><h2><ShieldCheck :size="18"/>运行维护</h2><button class="btn" :disabled="busy" @click="maintenance">{{health.runtime.mode==='draining'?'恢复写入':'进入停写维护'}}</button></header><dl><div><dt>写入状态</dt><dd>{{health.runtime.acceptsWrites===false?'停写排空':'可接收写入'}}</dd></div><div><dt>在途写入</dt><dd>{{health.runtime.activeWrites??0}}</dd></div><div><dt>待核对</dt><dd>{{health.pendingReconciliation}}</dd></div><div><dt>重操作 / 排队</dt><dd>{{health.capacity.activeHeavy}} / {{health.capacity.queuedHeavy}}</dd></div></dl><div v-if="health.backup" class="operations-backup"><strong>备份：{{({missing:'尚无已校验备份',invalid:'记录无效，需要核对',stale:'已超过24小时','local-only':'本地已校验，独立副本待验',healthy:'同代及独立副本已校验'} as Record<string,string>)[health.backup.status]??health.backup.status}}</strong><p>RPO目标24小时 · 一致性时点 {{health.backup.cutAt?timestamp(health.backup.cutAt):'尚无记录'}} · 独立加密副本{{health.backup.independentCopyVerified?'已验证':'未验证'}}</p></div><details><summary>备份和恢复说明</summary><p>备份必须同时包含官方存储及本机控制面。停写后仍需通过项目备份工具受控停止服务、校验同代清单，并把加密副本复制到配置的独立位置。此按钮只负责停写，不代表备份已完成。</p></details></section>
<p v-if="error" class="error-state" role="alert">{{error}}<span> 当前输入未被自动放弃；若找不到操作记录，请先刷新目标分支核对，不要盲目重复提交。</span></p><div class="operations-toolbar"><label>状态<select v-model="filter" aria-label="筛选操作状态"><option value="">全部状态</option><option v-for="(label,state) in labels" :key="state" :value="state">{{label}}</option></select></label><span>{{total}} 条可见操作</span></div>
<p v-if="loading" role="status"><LoaderCircle class="spin" :size="17"/>正在读取操作记录…</p><div v-else class="operations-layout"><div class="panel operations-table"><table><thead><tr><th>操作 / 项目</th><th>操作人</th><th>状态</th><th>最近更新</th><th>核对</th></tr></thead><tbody><tr v-for="item in items" :key="item.id" :class="{selected:selected?.id===item.id}"><td><strong>{{item.kind}}</strong><small>{{item.key?item.key.namespace+'/'+item.key.repo:'全局配置'}}<span v-if="item.ref"> · {{item.ref}}</span></small></td><td>{{item.actorName}}</td><td><span :class="['operation-status',item.state]">{{labels[item.state]??item.state}}</span></td><td>{{timestamp(item.updatedAt)}}</td><td><button class="btn btn-ghost" @click="choose(item)">详情</button></td></tr></tbody></table><div v-if="!items.length" class="empty"><ClipboardCheck :size="30"/><h3>没有匹配的操作</h3><p>此处记录需要明确提交的操作；原始输入保留和查询不会生成分支提交。</p></div><footer><span>第 {{page}} 页</span><button class="btn" :disabled="page<=1" @click="page--;load()">上一页</button><button class="btn" :disabled="page*30>=total" @click="page++;load()">下一页</button></footer></div>
<aside v-if="selected" class="panel operation-detail"><h2>操作证据</h2><code>{{selected.id}}</code><dl><dt>状态</dt><dd>{{labels[selected.state]}}</dd><dt>登记时间</dt><dd>{{timestamp(selected.createdAt)}}</dd><dt>核对说明</dt><dd>{{selected.reasonCode||'暂无故障说明'}}</dd></dl><h3>固定结果锚点</h3><pre>{{JSON.stringify(selected.anchors,null,2)}}</pre><p>缺少证据时保持“待核对”。不会通过改状态替代真实提交、独立复核或发布。</p><button v-if="owner&&['running','prepared','reconciliation-required'].includes(selected.state)" class="btn btn-primary" :disabled="busy" @click="reconcile"><LoaderCircle v-if="busy" class="spin" :size="15"/>读取证据并核对</button><RouterLink v-if="selected.key" class="btn" :to="'/repos/'+encodeURIComponent(selected.key.namespace)+'/'+encodeURIComponent(selected.key.repo)+'/versions'">查看项目版本</RouterLink></aside></div></section></template>
<style scoped>.operations-page{padding:30px var(--page-gutter);max-width:100%;min-width:0}.page-title-row{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:24px}.page-title-row h1{display:flex;align-items:center;gap:10px;margin:9px 0;font-size:26px}.page-title-row p,.operations-health p{color:var(--muted);line-height:1.8;font-size:13px}.operations-health{padding:20px;margin-bottom:22px}.operations-health header{display:flex;justify-content:space-between;align-items:center}.operations-health h2{display:flex;gap:8px;font-size:16px;align-items:center}.operations-health dl{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.operations-health dt{color:var(--muted);font-size:12px}.operations-health dd{margin:6px 0;font-size:19px}.operations-backup{border-top:1px solid var(--line);padding-top:14px;margin:16px 0;font-size:13px}.operations-health summary{color:var(--muted);font-size:12px;cursor:pointer}.operations-toolbar{display:flex;gap:18px;align-items:center;margin:20px 0;color:var(--muted);font-size:13px}.operations-toolbar label{display:flex;gap:10px;align-items:center}.operations-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,350px);gap:20px}.operations-layout:not(:has(aside)){grid-template-columns:minmax(0,1fr)}.operations-table{overflow:auto;min-width:0}.operations-table table{width:100%;border-collapse:collapse;min-width:600px;font-size:13px}.operations-table td,.operations-table th{padding:14px;text-align:left;border-bottom:1px solid var(--line)}.operations-table th{color:var(--muted)}.operations-table small{display:block;margin-top:7px;color:var(--muted)}.operations-table .selected{background:var(--primary-soft)}.operations-table footer{display:flex;gap:10px;align-items:center;justify-content:flex-end;padding:15px}.operations-table footer>span{margin-right:auto;color:var(--muted)}.operation-status{font-size:12px}.operation-status.succeeded{color:var(--success)}.operation-status.reconciliation-required{color:var(--warning)}.operation-status.failed{color:var(--danger)}.operation-detail{padding:20px;min-width:0;align-self:start}.operation-detail h2{font-size:17px;margin-bottom:12px}.operation-detail>code{font-size:12px;overflow-wrap:anywhere}.operation-detail dt{color:var(--muted);font-size:12px;margin-top:17px}.operation-detail dd{margin:6px 0;font-size:13px;overflow-wrap:anywhere}.operation-detail h3{font-size:13px;margin-top:22px}.operation-detail pre{max-height:260px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--bg);padding:12px;font-size:11px}.operation-detail p{color:var(--muted);font-size:12px;line-height:1.8}.operation-detail .btn{margin:8px 8px 0 0}@media(max-width:900px){.operations-layout{grid-template-columns:1fr}.operations-health dl{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.page-title-row{flex-wrap:wrap}.operations-health header{gap:12px;flex-wrap:wrap}}</style>
